import React, { useState } from 'react';

const LoginForm = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [dbStatus, setDbStatus] = useState(null);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch('http://localhost/sistema_ia/backend/login.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ usuario: username, contrasena: password }),
      });

      const data = await response.json();

      if (data.success) {
        onLogin({
          username,
          password,
          role: data.rol,
          name: data.name,
          initial: data.initial,
        });
      } else {
        setError(data.error || 'Error desconocido');
      }
    } catch (error) {
      setError('❌ Error al conectar con el servidor');
    }
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  const verificarConexion = async () => {
    try {
      const response = await fetch('http://localhost/sistema_ia/backend/verificar_conexion.php');
      const data = await response.json();
      if (data.success) {
        setDbStatus('✅ Conexión exitosa');
      } else {
        setDbStatus(`❌ Error: ${data.error}`);
      }
    } catch (error) {
      setDbStatus('❌ No se pudo conectar con el servidor');
    }
  };

  return (
    <div className="max-w-md w-full bg-white rounded-xl shadow-lg p-8">
      <div className="text-center mb-8">
        <h1 className="text-3xl font-bold text-gray-800">Luis Espinal</h1>
        <p className="text-gray-600 mt-2">Sistema de Gestión Académica</p>
      </div>
      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label htmlFor="username" className="block text-sm font-medium text-gray-700 mb-1">
            Usuario
          </label>
          <input
            type="text"
            id="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition"
            placeholder="Ingresa tu usuario"
            required
          />
        </div>
        <div>
          <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
            Contraseña
          </label>
          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-transparent transition pr-10"
              placeholder="Ingresa tu contraseña"
              required
            />
            <button
              type="button"
              onClick={togglePasswordVisibility}
              className="absolute right-3 top-1/2 transform -translate-y-1/2 text-sm text-blue-600 hover:underline focus:outline-none"
            >
              {showPassword ? 'Ocultar' : 'Ver'}
            </button>
          </div>
        </div>

        <button
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg transition duration-200"
        >
          Iniciar sesión
        </button>

        <button
          type="button"
          onClick={verificarConexion}
          className="w-full mt-2 bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded-lg transition duration-200"
        >
          Verificar Conexión
        </button>

        {error && (
          <p className="text-sm text-center mt-2 text-red-500">
            {error}
          </p>
        )}

        {dbStatus && (
          <p className="text-sm text-center mt-2 text-gray-700">
            {dbStatus}
          </p>
        )}
      </form>
    </div>
  );
};

export default LoginForm;
